  return [
    {
      type: 'turn/start', seq: 0, time: 1,
      data: { turn: 1, trigger: { kind: 'message', source: { kind: 'user' } } },
    },
    { type: 'user/message', seq: 1, time: 2, data: prompt, surfaceOp: 'append' },
    { type: 'step/start', seq: 2, time: 3, data: { turn: 1, step: 1 } },
